// A .d.ts-less CJS package whose shipped JS does NOT typecheck under the
// program's tsconfig (checkJs would flag the string/number comparison and
// the bare Array generic). It is never opted in, so it never joins the
// checker's program, whatever other package compiles.
'use strict';

/** @type {Array} */
const bag = [];

/** @type {number} */
const VERSION = 'one'; // a checkJs type error, deliberately
void VERSION;

function pick(v) {
  if (v < 'x') return 'low';
  return 'high';
}

module.exports = function label(n) {
  bag.push(n);
  return 'typegapped:' + pick(n) + ':' + bag.length;
};
